const input = $('Entrada').first().json;
const query = String(input.query || '').trim();
const projFilter = String(input.project || '').trim();

const STOP = new Set(['de', 'da', 'do', 'das', 'dos', 'a', 'o', 'as', 'os', 'e', 'em', 'no', 'na', 'nos', 'nas', 'para', 'pra', 'com', 'um', 'uma']);
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const tokens = (s) => norm(s).split(' ').filter(w => w.length > 1 && !STOP.has(w));

const projects = {};
for (const p of ($('Buscar projetos').first().json.results || [])) projects[p.id] = p.inbox_project ? 'Entrada' : p.name;

const tasks = [];
for (const it of $input.all()) for (const t of (it.json.results || [])) tasks.push(t);
const byId = {};
for (const t of tasks) byId[t.id] = t;

let pool = tasks.filter(t => !t.checked && !t.is_deleted);
let project_note = '';
if (projFilter) {
  const nf = norm(projFilter);
  let ids = Object.keys(projects).filter(id => norm(projects[id]) === nf);
  if (!ids.length) ids = Object.keys(projects).filter(id => { const np = norm(projects[id]); return np && (np.includes(nf) || nf.includes(np)); });
  if (ids.length) pool = pool.filter(t => ids.includes(t.project_id));
  else project_note = 'projeto "' + projFilter + '" não existe; procurei em todos';
}

const nq = norm(query);
const tq = tokens(query);
const scored = [];
for (const t of pool) {
  const nt = norm(t.content);
  if (!nt || !nq) continue;
  let score = 0;
  if (nt === nq) score = 100;
  else if ((nt.includes(nq) && nq.length >= 3) || (nq.includes(nt) && nt.length >= 3)) score = 80;
  else {
    const tt = tokens(t.content);
    if (tq.length && tt.length) {
      const inter = tq.filter(x => tt.includes(x)).length;
      const j = inter / new Set([...tq, ...tt]).size;
      if (j === 1) score = 90; // mesmas palavras, fora artigos/preposições
      else if (j >= 0.5) score = Math.round(j * 70);
    }
  }
  if (score > 0) scored.push({ score, t });
}
scored.sort((a, b) => (b.score - a.score) || (Math.abs(a.t.content.length - query.length) - Math.abs(b.t.content.length - query.length)));

const view = ({ t, score }) => ({
  id: t.id,
  content: t.content,
  description: t.description || '',
  project: projects[t.project_id] || '?',
  project_id: t.project_id,
  section_id: t.section_id || null,
  parent_id: t.parent_id || null,
  parent_content: t.parent_id && byId[t.parent_id] ? byId[t.parent_id].content : null,
  priority: t.priority,
  due: t.due || null,
  score,
});

const exact = scored.filter(s => s.score === 100);
const strong = scored.filter(s => s.score >= 80);
let status = 'none';
let best = null;
let candidates = [];
if (exact.length === 1) { status = 'one'; best = view(exact[0]); }
else if (exact.length > 1) { status = 'many'; candidates = exact.slice(0, 5).map(view); }
else if (strong.length === 1) { status = 'one'; best = view(strong[0]); }
else if (strong.length > 1) { status = 'many'; candidates = strong.slice(0, 5).map(view); }
else if (scored.length) { status = 'many'; candidates = scored.slice(0, 5).map(view); }

return [{ json: { status, query, project_filter: projFilter, project_note, best, candidates: best ? [best] : candidates, total_open: pool.length } }];
